import urllib.request
import urllib.error
import json

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        req = urllib.request.Request(url)
        req.add_header('Accept', 'application/json')
        try:
            response = urllib.request.urlopen(req, timeout=self.timeout)
            body = response.read().decode('utf-8')
            return body
        except urllib.error.URLError as e:
            if isinstance(e.reason, tuple) and len(e.reason) >= 2:
                status_code = e.reason[1]
                if 400 <= status_code < 500 and status_code != 429:
                    raise ClientError(f'Client error: {status_code}')
                elif status_code == 429:
                    for i in range(3):
                        if i > 0:
                            import time
                            time.sleep(0.5 * (2 ** (i - 1)))
                        try:
                            response = urllib.request.urlopen(req, timeout=self.timeout)
                            body = response.read().decode('utf-8')
                            return body
                        except urllib.error.URLError:
                            continue
                    raise RateLimitError('Rate limit still not cleared')
            else:
                raise ConnectionError(f'Connection error: {e.reason}')
        except urllib.error.HTTPError as e:
            status_code = e.code
            if status_code == 429:
                for i in range(3):
                    if i > 0:
                        import time
                        time.sleep(0.5 * (2 ** (i - 1)))
                    try:
                        response = urllib.request.urlopen(req, timeout=self.timeout)
                        body = response.read().decode('utf-8')
                        return body
                    except urllib.error.HTTPError:
                        continue
                    except urllib.error.URLError:
                        raise ConnectionError(f'Connection error: {e.reason}')
            elif 500 <= status_code < 600:
                import time
                time.sleep(1)
                try:
                    response = urllib.request.urlopen(req, timeout=self.timeout)
                    body = response.read().decode('utf-8')
                    return body
                except urllib.error.HTTPError:
                    raise ServerError(f'Server error: {status_code}')
                except urllib.error.URLError:
                    raise ConnectionError(f'Connection error: {e.reason}')
            else:
                raise ClientError(f'Client error: {status_code}')
